payload.query:
mutation courseElementProgressSave($elementId: String!, $practiceId: String, $code: String!, $signatures: [String!], $answer: String, $educontLessonId: String) {
  courseElementProgressSave(
    elementId: $elementId
    practiceId: $practiceId
    code: $code
    signatures: $signatures
    answer: $answer
    educontLessonId: $educontLessonId
  ) {
    passed
    recomendation
  }
}
